import { readFileSync } from 'node:fs';
import {
  creationEvent,
  importEvent,
  seedDocument,
  seedFolder,
  seedTag,
  seedWorkspace,
  type CoreDoubleFile,
  type CoreDoubleState,
} from '../../src/test/coreDouble';

/** Real files of each format, generated by scripts/make-library-fixtures.py. */
const FIXTURES = new URL('../fixtures/library/', import.meta.url);

export function fixtureBytes(name: string): Buffer {
  return readFileSync(new URL(name, FIXTURES));
}

/** Bytes of a fixture, in base64, to seed a document of the double (previews read them). */
export function fixtureBase64(name: string): string {
  return fixtureBytes(name).toString('base64');
}

/** Text of a fixture in UTF-8 (TXT, CSV, JSON), as the native extractor keeps it. */
export function fixtureText(name: string): string {
  return fixtureBytes(name).toString('utf8');
}

/** Text the native core extracts from cours-electronique.docx: one line per paragraph. */
export const DOCX_TEXT = 'Loi d’Ohm\nU = R × I\nLes résistances en série s’additionnent.';

/**
 * A file the next file picker (or drop) returns, with the real bytes of a fixture. The double cannot read a
 * Word document: it is given the text the native extractor produces from it. PDF text is extracted by pdf.js in
 * the page, from the bytes.
 */
export function pickedFixture(name: string): CoreDoubleFile {
  const extension = name.split('.').at(-1);
  if (extension === 'docx') {
    return { name, base64: fixtureBase64(name), text: DOCX_TEXT };
  }
  if (extension === 'txt' || extension === 'csv' || extension === 'json' || extension === 'md') {
    return { name, text: fixtureText(name) };
  }
  return { name, base64: fixtureBase64(name) };
}

/** A Library like a user's after a few imports: two workspaces, folders, tags, one document per format. */
export function libraryState() {
  const hour = 60 * 60 * 1000;
  const electronics = seedWorkspace('Électronique', {
    icon: 'cpu',
    description: 'Cours, projets et fiches de composants.',
    ageMs: 240 * hour,
  });
  const studies = seedWorkspace('Études supérieures', {
    icon: 'graduation-cap',
    color: 'blue',
    ageMs: 200 * hour,
  });
  const components = seedFolder(electronics, 'Composants');
  const courses = seedFolder(electronics, 'Cours');
  const semester = seedFolder(electronics, 'Semestre 1', courses);
  // The interface creates tags without a color for now: so do the seeds.
  const tagComponents = seedTag('Composants', 'neutral');
  const tagExam = seedTag('Examen', 'neutral');
  const tagProject = seedTag('Projet NE555', 'neutral');
  const pdf = seedDocument('fiche-ne555.pdf', {
    title: 'Fiche technique NE555',
    workspaceId: electronics.workspace.id,
    folderId: components.id,
    fileSize: fixtureBytes('fiche-ne555.pdf').byteLength,
    base64: fixtureBase64('fiche-ne555.pdf'),
    content:
      'Timer NE555\nFiche technique : réglage du montage astable\n\nBrochage\nBroche 8 : alimentation VCC',
    metadata: { format: 'pdf', pageCount: 2 },
    isFavorite: true,
    tagIds: [tagComponents.id, tagProject.id],
    ageMs: 2 * hour,
  });
  const docx = seedDocument('cours-electronique.docx', {
    title: 'Cours d’électricité générale',
    workspaceId: electronics.workspace.id,
    folderId: semester.id,
    fileSize: fixtureBytes('cours-electronique.docx').byteLength,
    base64: fixtureBase64('cours-electronique.docx'),
    content: DOCX_TEXT,
    metadata: {
      format: 'docx',
      documentTitle: 'Électricité générale',
      author: 'Alice',
      sourceModifiedAt: Date.now() - 400 * hour,
    },
    tagIds: [tagExam.id],
    ageMs: 30 * hour,
  });
  const png = seedDocument('schema-montage.png', {
    title: 'Schéma du montage astable',
    workspaceId: electronics.workspace.id,
    fileSize: fixtureBytes('schema-montage.png').byteLength,
    base64: fixtureBase64('schema-montage.png'),
    metadata: { format: 'png', width: 48, height: 32 },
    tagIds: [tagProject.id],
    ageMs: 5 * hour,
  });
  const txt = seedDocument('notes-de-cours.txt', {
    title: 'Notes de cours',
    workspaceId: studies.workspace.id,
    fileSize: fixtureBytes('notes-de-cours.txt').byteLength,
    base64: fixtureBase64('notes-de-cours.txt'),
    content: fixtureText('notes-de-cours.txt'),
    metadata: { format: 'txt', encoding: 'utf-8' },
    ageMs: 50 * hour,
  });
  const csv = seedDocument('composants.csv', {
    title: 'Liste des composants',
    workspaceId: electronics.workspace.id,
    folderId: components.id,
    fileSize: fixtureBytes('composants.csv').byteLength,
    base64: fixtureBase64('composants.csv'),
    content: fixtureText('composants.csv'),
    metadata: { format: 'csv', encoding: 'utf-8' },
    tagIds: [tagComponents.id],
    ageMs: 80 * hour,
  });
  const json = seedDocument('brochage.json', {
    title: 'Brochage du NE555',
    fileSize: fixtureBytes('brochage.json').byteLength,
    base64: fixtureBase64('brochage.json'),
    content: 'broches[0].nom: VCC\nbroches[0].numero: 8\ncomposant: NE555',
    metadata: { format: 'json' },
    ageMs: 120 * hour,
  });
  const broken = seedDocument('export-casse.json', {
    title: 'export-casse',
    fileSize: fixtureBytes('export-casse.json').byteLength,
    base64: fixtureBase64('export-casse.json'),
    indexingStatus: 'failed',
    metadata: { format: 'json', extractionIssue: 'invalid_json' },
    ageMs: 150 * hour,
  });
  const documents = [pdf, docx, png, txt, csv, json, broken];
  return {
    electronics,
    studies,
    folders: { components, courses, semester },
    tags: { components: tagComponents, exam: tagExam, project: tagProject },
    documents: { pdf, docx, png, txt, csv, json, broken },
    state: {
      workspaces: [electronics, studies],
      folders: [components, courses, semester],
      tags: [tagComponents, tagExam, tagProject],
      documents,
      // The timeline is kept oldest first.
      events: [...[electronics, studies].map(creationEvent), ...documents.map(importEvent)].sort(
        (a, b) => a.createdAt - b.createdAt,
      ),
    } satisfies Partial<CoreDoubleState>,
  };
}
